Here is the commit message:
net/mana: Null service_wq on setup error to prevent double
 destroy

In mana_gd_setup() error path, set gc->service_wq to NULL after
destroy_workqueue() to match the cleanup in mana_gd_cleanup().
This prevents a use-after-free if the workqueue pointer is checked
after a failed setup.

Fixes: f975a0955276 ("net: mana: Fix double destroy_workqueue on service rescan PCI path")
Signed-off-by: Shiraz Saleem <shirazsaleem@microsoft.com>
Signed-off-by: Konstantin Taranov <kotaranov@microsoft.com>
Reviewed-by: Simon Horman <horms@kernel.org>
Link: https://patch.msgid.link/20260309172443.688392-1-kotaranov@linux.microsoft.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
After destroying the workqueue in the error path of mana_gd_setup, the pointer gc->service_wq is not set to NULL. This can lead to a subsequent double destroy or use-after-free if the pointer is later checked and used (e.g., in mana_gd_cleanup).

Here is the patch:

 static int mana_gd_setup(struct pci_dev *pdev)
 {
 	struct gdma_context *gc = pci_get_drvdata(pdev);
 	int err;

 	mana_gd_init_registers(pdev);
 	mana_smc_init(&gc->shm_channel, gc->dev, gc->shm_base);

 	gc->service_wq = alloc_ordered_workqueue("gdma_service_wq", 0);
 	if (!gc->service_wq)
 		return -ENOMEM;

 	err = mana_gd_setup_hwc_irqs(pdev);
 	if (err) {
 		dev_err(gc->dev, "Failed to setup IRQs for HWC creation: %d\n",
 			err);
 		goto free_workqueue;
 	}

 	err = mana_hwc_create_channel(gc);
 	if (err)
 		goto remove_irq;

 	err = mana_gd_verify_vf_version(pdev);
 	if (err)
 		goto destroy_hwc;

 	err = mana_gd_query_max_resources(pdev);
 	if (err)
 		goto destroy_hwc;

 	err = mana_gd_setup_remaining_irqs(pdev);
 	if (err) {
 		dev_err(gc->dev, "Failed to setup remaining IRQs: %d", err);
 		goto destroy_hwc;
 	}

 	err = mana_gd_detect_devices(pdev);
 	if (err)
 		goto destroy_hwc;

 	dev_dbg(&pdev->dev, "mana gdma setup successful\n");
 	return 0;

 destroy_hwc:
 	mana_hwc_destroy_channel(gc);
 remove_irq:
 	mana_gd_remove_irqs(pdev);
 free_workqueue:
 	destroy_workqueue(gc->service_wq);
+	gc->service_wq = NULL;
 	dev_err(&pdev->dev, "%s failed (error %d)\n", __func__, err);
 	return err;
 }



